SET client_encoding = 'UTF8';
BEGIN;
UPDATE articulos SET metadata = '{"areas": ["sociabilidad", "creatividad", "afectividad"], "unidades": ["manada", "compañía", "tropa", "avanzada", "clan"], "duracion": "20 minutos", "cantidad": "04 participantes", "lugares": ["Interior", "Salón", "Exterior", "Campo Abierto"], "materiales": ["Tarjetas de Misiones"], "objetivos": ["Fomentar la comunicación e interpretación", "Estimular la agilidad mental", "Trabajo en equipo", "Fomentar un entorno de confianza"], "justificacion_areas": "El Desafío del Silencio Comunicativo potencia la sociabilidad al enseñar a los beneficiarios de todas las unidades (desde Manada hasta Clan) a escucharse visualmente y respetar los tiempos de sus compañeros. Desarrolla la creatividad al requerir soluciones ingeniosas de expresión corporal frente a misiones complejas de resolución estratégica. Fortalece la afectividad al afianzar la empatía no verbal, el autocontrol y la paciencia dentro del equipo.", "variaciones": "<b>Silencio en la Selva (Manada):</b> Los lobatos se comunican en clave secreta no verbal para no ser descubiertos por Shere Khan.<br><b>Cadena de Nudos Silenciosa (Compañía/Tropa):</b> Transmitir las instrucciones para realizar una estructura scout utilizando únicamente mímica de manos.<br><b>Resoluición de Dilemas de Pionerismo Silencioso (Avanzada/Clan):</b> La unidad mayor debe coordinar la resolución de un circuito técnico o dilema de servicio comunicándose solo con señas avanzadas.", "recomendaciones": "Generar un clima de profunda concentración y respeto por la palabra no verbal. En Avanzada y Clan, adaptar las tarjetas con desafíos de lógica y liderazgo de equipo.", "objetivos_educativos": [{"id": "b69188bf-2391-43c1-a885-abd1b13912be", "area": "Sociabilidad", "unidad": "Manada", "texto": "Acepto las reglas que se ponen en mi casa, en la escuela y en la Manada.", "como_se_cumple": "Acatando con lealtad la regla de no hablar durante el desarrollo de la prueba."}, {"id": "2394dd5b-87b9-4f3d-9cdd-a42649139782", "area": "Sociabilidad", "unidad": "Manada", "texto": "Comprendo y respeto las normas que se han puesto en mi casa y en la escuela, aunque no siempre esté de acuerdo con ellas", "como_se_cumple": "Respetando los turnos de expresión no verbal de mis compañeros de seisena."}, {"id": "007e85ea-2b06-48c2-8ac1-873d59643aae", "area": "Sociabilidad", "unidad": "Compañía", "texto": "Conozco y respeto las principales normas de convivencia.", "como_se_cumple": "Fomentando el respeto y la atención dedicada hacia las señas de las demás personas."}, {"id": "de2f5693-de4b-48f1-b870-3c62be99aea8", "area": "Sociabilidad", "unidad": "Compañía", "texto": "Respeto las normas de convivencia de los distintos ambientes en que actúo, aunque no siempre esté de acuerdo con ellas.", "como_se_cumple": "Promoviendo un ambiente de integración, escucha atenta y lealtad de patrulla."}, {"id": "857f21bc-db3c-4e5e-bcd5-d3d331276fad", "area": "Sociabilidad", "unidad": "Tropa", "texto": "Conozco y respeto las principales normas de convivencia.", "como_se_cumple": "Cumpliendo las consignas del silencio scout con responsabilidad compartida."}, {"id": "bbc48d53-f4aa-4de7-84d4-95614df76034", "area": "Sociabilidad", "unidad": "Tropa", "texto": "Respeto las normas de convivencia de los distintos ambientes en que actúo, aunque no siempre esté de acuerdo con ellas.", "como_se_cumple": "Afianzando la cohesión y hermandad comunitaria en toda la Tropa."}, {"id": "3fd19eb4-737c-43c5-9ea8-5e5307ce0309", "area": "Sociabilidad", "unidad": "Avanzada", "texto": "Cumple las normas que la sociedad se ha dado, evaluándolas con responsabilidad y sin renunciar a cambiarlas.", "como_se_cumple": "Asumiendo el silencio reflexivo como una herramienta de autorregulación y madurez grupal."}, {"id": "d24ef58c-8306-4065-9625-8f5e663febcb", "area": "Afectividad", "unidad": "Avanzada", "texto": "Practica una conducta asertiva y una actitud afectuosa hacia las demás personas, sin inhibiciones ni agresividad.", "como_se_cumple": "Expresando empatía no verbal y apoyo asertivo a los compañeros durante retos complejos."}, {"id": "91e60eba-e267-4d1a-b27b-ef61a7b03b31", "area": "Creatividad", "unidad": "Clan", "texto": "Expresa lo que piensa y siente a través de distintos medios, creando en los ambientes en que actúa espacios gratos que faciliten el encuentro y el perfeccionamiento entre las personas.", "como_se_cumple": "Innovando en formas no verbales de comunicación para construir comunidad y encuentro interpersonal."}, {"id": "d0ba748f-313b-4ffe-b2a3-fb21c1f8943f", "area": "Afectividad", "unidad": "Clan", "texto": "Practica una conducta asertiva y una actitud afectuosa hacia las demás personas, sin inhibiciones ni agresividad.", "como_se_cumple": "Fomentando el clima de confianza y la contención afectiva madura en el Clan."}]}'::jsonb WHERE slug = 'el-desafio-del-silencio-comunicativo';
DELETE FROM articulo_objetivos_educativos WHERE articulo_id = (SELECT id FROM articulos WHERE slug = 'el-desafio-del-silencio-comunicativo');
COMMIT;